"""Structured knowledge on the spectral field: 2-adic families, inheritance, concepts.

Facts are compressible exactly when they are generated by structure.  This
module represents structure with the field's own algebra:

- A taxonomy is a rooted tree.  A node's 2-adic code places its child index at
  depth ``i`` in bits ``[b(i-1), bi)``, root digit lowest.  Then ``y`` is an
  ancestor of ``x`` iff ``code(x) == code(y) (mod 2**(b*depth(y)))``: a family
  is a 2-adic ball, the kernel coset of a dyadic character, and membership is
  an exact phase comparison on the SPF ring.
- A property is stored as a minimal set of overrides ``(node, value)``.  The
  value of an entity is the value at its deepest overridden ancestor ("the most
  specific family wins").  The minimal set is small-parsimony on the tree.
- Unstored facts are inferred by inheritance.  A new entity is placed at the
  deepest family consistent with the few facts known about it.  A concept is
  the smallest family (ball) containing its examples.
- Trees can be induced from facts alone by average-linkage clustering, which
  recovers ultrametric structure.

Everything here is exact integer or combinatorial computation.  Gradient
baselines live in the experiment runner, not here.
"""

from __future__ import annotations

from dataclasses import dataclass, field

import numpy as np

UNKNOWN = -1
RING_BITS = 16


@dataclass
class Tree:
    """Rooted tree.  Node 0 is the root; ``parent[0] == -1``."""

    parent: np.ndarray
    children: list[list[int]]
    depth: np.ndarray
    leaves: np.ndarray  # node ids of leaves, in entity order
    code: np.ndarray | None = None  # 2-adic codes (balanced trees only)
    bits: int = 0  # bits per digit for codes

    @property
    def size(self) -> int:
        return int(self.parent.shape[0])

    def order(self) -> list[int]:
        """Nodes in breadth-first order (parents before children)."""

        out = [0]
        for node in out:
            out.extend(self.children[node])
        return out

    def ancestors(self, node: int) -> list[int]:
        chain = []
        while node != -1:
            chain.append(node)
            node = int(self.parent[node])
        return chain  # self first, root last


def balanced_tree(branching: int, depth: int) -> Tree:
    """Complete ``branching``-ary tree of the given depth with 2-adic codes."""

    bits = int(np.log2(branching))
    if 2**bits != branching:
        raise ValueError("branching must be a power of two for 2-adic codes")
    parent = [-1]
    depth_list = [0]
    code = [0]
    frontier = [0]
    for level in range(1, depth + 1):
        nxt = []
        for node in frontier:
            for digit in range(branching):
                parent.append(node)
                depth_list.append(level)
                code.append(code[node] + digit * (1 << (bits * (level - 1))))
                nxt.append(len(parent) - 1)
        frontier = nxt
    parent_arr = np.array(parent)
    children: list[list[int]] = [[] for _ in parent]
    for node, up in enumerate(parent):
        if up >= 0:
            children[up].append(node)
    return Tree(parent_arr, children, np.array(depth_list), np.array(frontier), np.array(code), bits)


def tree_from_linkage(linkage: np.ndarray, leaves: int) -> Tree:
    """Binary tree from a scipy linkage matrix; leaf ``i`` is entity ``i``."""

    total = 2 * leaves - 1
    # scipy ids: 0..leaves-1 leaves, leaves.. internal; relabel so root = 0.
    scipy_parent = np.full(total, -1)
    for row, (a, b, _h, _n) in enumerate(linkage):
        scipy_parent[int(a)] = leaves + row
        scipy_parent[int(b)] = leaves + row
    root = total - 1
    relabel = {root: 0}
    queue = [root]
    kids: dict[int, list[int]] = {}
    for node in range(total):
        up = scipy_parent[node]
        if up >= 0:
            kids.setdefault(int(up), []).append(node)
    for node in queue:
        for child in kids.get(node, []):
            relabel[child] = len(relabel)
            queue.append(child)
    parent = np.full(total, -1)
    for node in range(total):
        up = scipy_parent[node]
        if up >= 0:
            parent[relabel[node]] = relabel[int(up)]
    children: list[list[int]] = [[] for _ in range(total)]
    for node in range(1, total):
        children[int(parent[node])].append(node)
    depth = np.zeros(total, dtype=int)
    order = [0]
    for node in order:
        for child in children[node]:
            depth[child] = depth[node] + 1
            order.append(child)
    leaf_ids = np.array([relabel[i] for i in range(leaves)])
    return Tree(parent, children, depth, leaf_ids)


# ---------------------------------------------------------------------------
# Generative knowledge bases
# ---------------------------------------------------------------------------


def tree_generated_values(
    tree: Tree,
    values: int,
    mutation: float,
    exception: float,
    rng: np.random.Generator,
) -> tuple[np.ndarray, int]:
    """One property generated down the tree: root value, mutations, leaf exceptions.

    Returns leaf values (entity order) and the number of generator overrides
    (root + mutated internal nodes + leaf exceptions), the property's true
    description length in entries.
    """

    value = np.zeros(tree.size, dtype=int)
    value[0] = rng.integers(values)
    overrides = 1
    leaf_set = set(tree.leaves.tolist())
    for node in tree.order()[1:]:
        inherited = value[tree.parent[node]]
        rate = exception if node in leaf_set else mutation
        if rng.random() < rate:
            new = int(rng.integers(values - 1))
            value[node] = new + (new >= inherited)
            overrides += 1
        else:
            value[node] = inherited
    return value[tree.leaves], overrides


@dataclass
class KnowledgeBase:
    facts: np.ndarray  # (entities, attributes) values
    kind: np.ndarray  # per attribute: "tree" or "random"
    generator_entries: int  # true override count over tree attributes
    notes: dict = field(default_factory=dict)


def taxonomy_kb(
    tree: Tree,
    attributes: int,
    values: int,
    mutation: float,
    exception: float,
    random_fraction: float,
    rng: np.random.Generator,
) -> KnowledgeBase:
    entities = tree.leaves.shape[0]
    facts = np.zeros((entities, attributes), dtype=int)
    kind = np.array(["tree"] * attributes, dtype=object)
    random_count = int(round(random_fraction * attributes))
    kind[:random_count] = "random"
    entries = 0
    for a in range(attributes):
        if kind[a] == "random":
            facts[:, a] = rng.integers(values, size=entities)
        else:
            facts[:, a], used = tree_generated_values(tree, values, mutation, exception, rng)
            entries += used
    return KnowledgeBase(facts, kind, entries)


# ---------------------------------------------------------------------------
# Compression by parsimony: minimal override sets
# ---------------------------------------------------------------------------


@dataclass
class Program:
    """Override table per attribute: node -> value.  Root is always present."""

    overrides: list[dict[int, int]]
    labels: np.ndarray  # (attributes, nodes) effective value at every node

    def entries(self) -> int:
        return sum(len(table) for table in self.overrides)


def compress(tree: Tree, observed: np.ndarray, values: int) -> Program:
    """Minimal override set reproducing every observed leaf value.

    ``observed`` is (entities, attributes) with UNKNOWN for missing cells.
    Small parsimony with unit change cost: cost(n, v) is the fewest value
    changes inside n's subtree if n carries v.  Unknown leaves are free, so
    their prediction is whatever they inherit.  Vectorized over attributes.
    """

    attrs = observed.shape[1]
    big = 10**9
    cost = np.zeros((tree.size, attrs, values), dtype=np.int64)
    leaf_of = {int(node): i for i, node in enumerate(tree.leaves)}
    order = tree.order()
    for node in reversed(order):
        if node in leaf_of:
            obs = observed[leaf_of[node]]
            leaf_cost = np.full((attrs, values), big, dtype=np.int64)
            known = obs != UNKNOWN
            leaf_cost[~known] = 0
            leaf_cost[np.where(known)[0], obs[known]] = 0
            cost[node] = leaf_cost
            continue
        total = np.zeros((attrs, values), dtype=np.int64)
        for child in tree.children[node]:
            child_cost = cost[child]
            switch = child_cost.min(-1, keepdims=True) + 1
            total += np.minimum(child_cost, switch)
        cost[node] = total
    labels = np.zeros((attrs, tree.size), dtype=int)
    overrides: list[dict[int, int]] = [dict() for _ in range(attrs)]
    root_choice = cost[0].argmin(-1)
    labels[:, 0] = root_choice
    for a in range(attrs):
        overrides[a][0] = int(root_choice[a])
    for node in order[1:]:
        up = labels[:, tree.parent[node]]
        child_cost = cost[node]
        keep = child_cost[np.arange(attrs), up]
        best = child_cost.argmin(-1)
        switch = child_cost[np.arange(attrs), best] + 1
        change = switch < keep
        labels[:, node] = np.where(change, best, up)
        for a in np.where(change)[0]:
            overrides[int(a)][node] = int(best[a])
    return Program(overrides, labels)


def predict(tree: Tree, program: Program) -> np.ndarray:
    """(entities, attributes) values by inheritance (labels at the leaves)."""

    return program.labels[:, tree.leaves].T


def program_bits(tree: Tree, program: Program, attributes: int, values: int) -> float:
    per_entry = np.log2(tree.size) + np.log2(values)
    header = attributes * np.log2(max(2, max(len(t) for t in program.overrides) + 1))
    return program.entries() * per_entry + header


# ---------------------------------------------------------------------------
# Exact execution with dyadic phase characters (balanced trees)
# ---------------------------------------------------------------------------


def phase_character(code: np.ndarray, level: int, bits: int) -> np.ndarray:
    """Phase code of the character with period 2**(bits*level) on the 2**16 ring.

    Two codes have equal phase iff they agree modulo 2**(bits*level), i.e. iff
    they lie in the same depth-``level`` family.
    """

    shift = RING_BITS - bits * level
    if shift < 0:
        raise ValueError("family depth exceeds one 16-bit channel")
    return (code.astype(np.int64) << shift) % (1 << RING_BITS)


def execute_by_characters(tree: Tree, program: Program, attribute: int, entity_codes: np.ndarray) -> np.ndarray:
    """Most-specific-family lookup using only phase-character equality.

    For each level from deepest to root, the stored overrides at that level
    form a dictionary keyed by their phase on that level's character; the first
    hit wins.  Equivalent to the inheritance labels when codes are exact.
    """

    if tree.code is None:
        raise ValueError("character execution needs 2-adic codes")
    max_depth = int(tree.depth.max())
    tables = {level: {} for level in range(max_depth + 1)}
    for node, value in program.overrides[attribute].items():
        level = int(tree.depth[node])
        key = int(phase_character(np.array([tree.code[node]]), level, tree.bits)[0])
        tables[level][key] = value
    out = np.full(entity_codes.shape[0], UNKNOWN)
    for level in range(max_depth, -1, -1):
        keys = phase_character(entity_codes, level, tree.bits)
        for i, key in enumerate(keys.tolist()):
            if out[i] == UNKNOWN and key in tables[level]:
                out[i] = tables[level][key]
    return out


# ---------------------------------------------------------------------------
# Tree induction from facts (coordinate induction)
# ---------------------------------------------------------------------------


def hamming_distances(observed: np.ndarray) -> np.ndarray:
    """Pairwise mismatch fraction over co-observed attributes (condensed form)."""

    from scipy.spatial.distance import squareform

    known = (observed != UNKNOWN).astype(np.float32)
    count = known @ known.T
    values = int(observed.max()) + 1
    agree = np.zeros_like(count)
    for v in range(values):
        hot = (observed == v).astype(np.float32)
        agree += hot @ hot.T
    distance = 1.0 - agree / np.maximum(count, 1.0)
    np.fill_diagonal(distance, 0.0)
    return squareform(distance, checks=False)


def induce_tree(observed: np.ndarray) -> Tree:
    from scipy.cluster.hierarchy import linkage

    condensed = hamming_distances(observed)
    return tree_from_linkage(linkage(condensed, method="average"), observed.shape[0])


# ---------------------------------------------------------------------------
# Reasoning about new entities and concepts
# ---------------------------------------------------------------------------


def place_entity(tree: Tree, program: Program, known: dict[int, int]) -> int:
    """Deepest node whose inherited values best match the known facts."""

    if not known:
        return 0
    attrs = np.array(list(known.keys()))
    vals = np.array(list(known.values()))
    matches = (program.labels[attrs] == vals[:, None]).sum(0)
    best = matches.max()
    candidates = np.where(matches == best)[0]
    return int(candidates[np.argmax(tree.depth[candidates])])


def concept_hull(tree: Tree, examples: list[int]) -> int:
    """Lowest common ancestor (smallest family) of the example leaves."""

    chains = [tree.ancestors(int(tree.leaves[e])) for e in examples]
    common = set(chains[0])
    for chain in chains[1:]:
        common &= set(chain)
    return max(common, key=lambda node: tree.depth[node])


def two_adic_hull(codes: np.ndarray, bits: int) -> tuple[int, int]:
    """Smallest 2-adic ball containing the codes: (level, code mod 2**(bits*level)).

    The level is the number of whole digits on which all codes agree, i.e.
    floor(min_i v2(code_i - code_0) / bits).
    """

    base = int(codes[0])
    valuation = 64
    for code in codes[1:]:
        diff = int(code) - base
        if diff:
            valuation = min(valuation, (diff & -diff).bit_length() - 1)
    level = valuation // bits
    return level, base % (1 << (bits * level)) if level < 64 else base


def leaves_under(tree: Tree, node: int) -> set[int]:
    leaf_index = {int(n): i for i, n in enumerate(tree.leaves)}
    out = set()
    stack = [node]
    while stack:
        current = stack.pop()
        if current in leaf_index:
            out.add(leaf_index[current])
        stack.extend(tree.children[current])
    return out


# ---------------------------------------------------------------------------
# Editing and conflicts
# ---------------------------------------------------------------------------


def relabel(tree: Tree, program: Program, attribute: int) -> None:
    """Recompute effective values of one attribute from its override table."""

    table = program.overrides[attribute]
    for node in tree.order():
        if node in table:
            program.labels[attribute, node] = table[node]
        else:
            program.labels[attribute, node] = program.labels[attribute, tree.parent[node]]


def edit_family(tree: Tree, program: Program, attribute: int, node: int, value: int, reset: bool = False) -> None:
    """Change one family-level fact.

    Default: change the family's default; members with deeper overrides keep
    them.  ``reset=True``: set every member, deleting deeper overrides of this
    attribute inside the family.
    """

    if reset:
        stack = list(tree.children[node])
        while stack:
            current = stack.pop()
            program.overrides[attribute].pop(current, None)
            stack.extend(tree.children[current])
    program.overrides[attribute][node] = value
    relabel(tree, program, attribute)


def is_ancestor(tree: Tree, up: int, node: int) -> bool:
    while node != -1:
        if node == up:
            return True
        node = int(tree.parent[node])
    return False


def product_conflicts(
    trees: tuple[Tree, Tree], keys: dict[tuple[int, int], int]
) -> list[tuple[tuple[int, int], tuple[int, int]]]:
    """Pairs of product-family facts that disagree on a nonempty, unresolved region.

    A key (n1, n2) is the family ball(n1) x ball(n2).  Two keys overlap iff their
    nodes are comparable on both axes; their meet is (deeper n1, deeper n2).
    The pair conflicts when the values differ, neither key is at least as
    specific as the other on both axes, and no key sits exactly at the meet.
    This is the Nixon diamond as a lattice computation.
    """

    first, second = trees
    items = list(keys.items())
    out = []
    for i in range(len(items)):
        for j in range(i + 1, len(items)):
            (a1, a2), va = items[i]
            (b1, b2), vb = items[j]
            if va == vb:
                continue
            comparable1 = is_ancestor(first, a1, b1) or is_ancestor(first, b1, a1)
            comparable2 = is_ancestor(second, a2, b2) or is_ancestor(second, b2, a2)
            if not (comparable1 and comparable2):
                continue
            a_more = is_ancestor(first, b1, a1) and is_ancestor(second, b2, a2)
            b_more = is_ancestor(first, a1, b1) and is_ancestor(second, a2, b2)
            if a_more or b_more:
                continue
            meet = (a1 if first.depth[a1] >= first.depth[b1] else b1, a2 if second.depth[a2] >= second.depth[b2] else b2)
            if meet not in keys:
                out.append(((a1, a2), (b1, b2)))
    return out
